export const backfillTasks = mutation({
  handler: async (ctx) => {
    const tasks = await ctx.db.query("tasks").collect();
    const updates = tasks.map((task) => {
      const needsIsCompleted = task.isCompleted === undefined;
      const hasStatus = task.status !== undefined;
      if (!needsIsCompleted && !hasStatus) {
        return null;
      }
      return ctx.db.replace(task._id, {
        text: task.text,
        runId: task.runId,
        isCompleted: task.isCompleted ?? false,
      });
    });
    await Promise.all(updates.filter(Boolean));
  },
});

